1	import { LANGUAGE_PROMPT_SUPPRESSION_DAYS } from './regionPrefCookie';
2	
3	/**
4	 * The one real-world SFCC site ID shared by all four EU-domestic PWA sites (`ZimmermannEUen`,
5	 * `ZimmermannEUfr`, `ZimmermannEUit`, `ZimmermannEUes` — see `config/sites.overlay.js`). A
6	 * single equality check against this covers all four and naturally excludes EU International
7	 * (`ZimmermannEUIntl`, its own separate SFCC site, English-only), which has no `sfccSiteId`
8	 * override and so never carries this value.
9	 */
10	export const EU_DOMESTIC_SFCC_SITE_ID = 'ZimmermannEU';
11	
12	/**
13	 * Primary-subtag language codes of the four EU-domestic sites' own locales (`en-GB`, `fr`,
14	 * `it`, `es` — `config/sites.overlay.js`). This predicate has no site config of its own to
15	 * derive the list from (it only receives already-extracted strings), so the four are named here
16	 * directly rather than threaded through as a parameter nothing else currently needs.
17	 */
18	export const SUPPORTED_EU_LANGUAGES: readonly string[] = ['en', 'fr', 'it', 'es'];
19	
20	const SECONDS_PER_DAY = 24 * 60 * 60;
21	
22	export type ShouldShowLanguagePromptInput = {
23	  /** The runtime's current PWA site's SFCC site id (e.g. `site.sfccSiteId`), or `undefined`. */
24	  readonly sfccSiteId: string | undefined;
25	  /** The current site's own language — a locale id/alias, e.g. `'fr'` or `'en-GB'`. */
26	  readonly currentLanguage: string;
27	  /** `navigator.languages`, most-preferred first, e.g. `['fr-FR', 'en-US']`. */
28	  readonly browserLanguages: readonly string[];
29	  /** The `l` value from `regionPrefCookie.ts`, in epoch **seconds** — `undefined` if never set. */
30	  readonly suppressedAt: number | undefined;
31	  /** The current time, in epoch **seconds** (same unit as `suppressedAt`). */
32	  readonly now: number;
33	};
34	
35	export type ShouldShowLanguagePromptResult =
36	  | { readonly show: true; readonly targetLanguage: string }
37	  | { readonly show: false };
38	
39	/** Lower-cases and takes the primary subtag of a BCP-47-ish tag: `'fr-FR'` -> `'fr'`. */
40	function primarySubtag(languageTag: string): string {
41	  return languageTag.split('-')[0].toLowerCase();
42	}
43	
44	/**
45	 * Pure predicate for the EU-domestic language-mismatch prompt (SFCC-689). Decides whether the
46	 * shopper's browser language disagrees with the storefront they're currently on, and if so,
47	 * which of the four EU languages to offer switching to.
48	 *
49	 * Both sides of the comparison are reduced to their primary subtag before comparing — browsers
50	 * report full tags (`fr-FR`, `it-CH`), and one of our own site locales is itself a full tag
51	 * (`en-GB`) rather than a bare code. Comparing full strings would make a French shopper
52	 * reporting `fr-FR` never match anything, and would make `en-GB` (our own English site's
53	 * locale) never match a browser reporting plain `en`.
54	 *
55	 * Only `browserLanguages[0]` (the browser's single most-preferred language) is evaluated, not
56	 * the full preference list — every branch this predicate needs to support describes "the
57	 * browser's language" as one signal, and scanning further down an unmatched preference list for
58	 * a supported one is a behaviour nothing has specified.
59	 *
60	 * The suppression window is enforced here, at read time, against `suppressedAt` +
61	 * `LANGUAGE_PROMPT_SUPPRESSION_DAYS` — not by the cookie's own expiry (see `regionPrefCookie.ts`).
62	 */
63	export function shouldShowLanguagePrompt(input: ShouldShowLanguagePromptInput): ShouldShowLanguagePromptResult {
64	  const { sfccSiteId, currentLanguage, browserLanguages, suppressedAt, now } = input;
65	
66	  if (sfccSiteId !== EU_DOMESTIC_SFCC_SITE_ID) {
67	    return { show: false };
68	  }
69	
70	  if (suppressedAt !== undefined) {
71	    const suppressionWindowEnd = suppressedAt + LANGUAGE_PROMPT_SUPPRESSION_DAYS * SECONDS_PER_DAY;
72	    if (now < suppressionWindowEnd) {
73	      return { show: false };
74	    }
75	  }
76	
77	  const browserLanguage = browserLanguages[0];
78	  if (!browserLanguage) {
79	    return { show: false };
80	  }
81	
82	  const browserPrimary = primarySubtag(browserLanguage);
83	  if (browserPrimary === primarySubtag(currentLanguage)) {
84	    return { show: false };
85	  }
86	
87	  if (SUPPORTED_EU_LANGUAGES.includes(browserPrimary)) {
88	    return { show: true, targetLanguage: browserPrimary };
89	  }
90	
91	  return { show: false };
92	}
93

